};

scwin.setHeader = function() {
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        submitDoneHandler : scwin.sbm_dts_Master_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);



    //----W-Craft WebSquare 변환 확인: AddRow----//
    dts_Master.AddRow();
    const sbmOptions2 = {
        id : "sbm_dts_Receiver",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Receiver=body.content",
        submitDoneHandler : scwin.sbm_dts_Receiver_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);



    // 파일: 가우스헤더 셋팅	

    //----W-Craft WebSquare 변환 확인: SetDataHeader----//
    dts_fileData.SetDataHeader("fileInfo:String,fileUrl:URL,FILE_NAME:String,FILE_SIZE:String,FILE_SEQ:String,NOTI_SVC_ID:String" + ",FILE_SIZE_VIEW:String");
    const sbmOptions3 = {
        id : "sbm_dts_fileData",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileData=body.content",
        submitDoneHandler : scwin.sbm_dts_fileData_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);

    //dts_fileData.AddRow();	

};

scwin.setData = function() {
    txb_fromName.setValue("기술상장심사");
    txb_fromEmail.setValue("krxtechlisting@krx.co.kr");
    txb_BccName.setValue("기술상장심사");
    txb_BccEmail.setValue("krxtechlisting@krx.co.kr");
};

scwin.initPage = function() {
    scwin.gNOTI_SVC_ID = $c.stf.getQuery(frame.srcUrl, "NOTI_SVC_ID");
    scwin.gAddInput = $c.stf.getQuery(frame.srcUrl, "ADD_INPUT");
    scwin.gPvd = $c.stf.getQuery(frame.srcUrl, "frameID");
    //alert('[gPvd]'+gPvd);
    //alert('[gNOTI_SVC_ID]'+gNOTI_SVC_ID);
    //alert('[gAddInput]'+gAddInput);
    if (scwin.gAddInput === 'Y') {
        scwin.read();
        scwin.setData();
    } else {
        scwin.setHeader();
        scwin.setData();
    }
};

scwin.read = function() {
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_Master=body.content",
        submitDoneHandler : scwin.sbm_dts_Master_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    //alert(url);
    const sbmOptions2 = {
        id : "sbm_dts_fileData",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_fileData=body.content",
        submitDoneHandler : scwin.sbm_dts_fileData_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


    const sbmOptions3 = {
        id : "sbm_dts_Receiver",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_Receiver=body.content",
        submitDoneHandler : scwin.sbm_dts_Receiver_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);


};


// 첨부파일 다운로드
$c.en.fn_filedown = function(vNotiSvcId, vSeq) {
    //var vNotiSvcId= getObjectValue(txb_NOTI_SVC_ID);
    //var vSeq= getObjectValue(txb_file_seq);

    let link = "/filedownload.do?NOTI_SVC_ID=" + vNotiSvcId + "&SEQ=" + vSeq + "&gubun=11";
    location.href = encodeURI(link);
};

scwin.hideDebugCtrls = function() {
    panel_debug.hide();
    //showObj(panel_BCC, false);

};

scwin.registerMail = function() {
    //alert_parse(dts_Receiver.Text, ",");return;
    if (scwin.fn_CheckForm() && scwin.checkFileSize()) {
        let msg = $c.stf.getMessageParam("MSG-A006", "전송");
        let res = window.confirm(msg);
        if (res) {
            let url = "/EmailMgt.do?method=sendSpecyValuEmail" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            //alert(dts_MASTER.Text);
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver, I:pFile=dts_fileData)";

            //----W-Craft WebSquare 변환 확인: post----//
            trs_Save.post();
        }
    }
};

/**
 * 전체 파일 사이즈 체크
 */
scwin.checkFileSize = function() {
    let totalFileSize = 0;
    let isValid = true;
    // TODO Stage2: 0-based 검토
    for (let i = 1; i <= dts_fileData.getRowCount(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > scwin.fileSizeLimit) {
        alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};
$c.en.fn_CheckForm = function() {
    let msg = "";
    if ($c.ut.email_chk(txb_fromEmail.getValue()) === false) {
        alert("잘못된 이메일 주소입니다.");

        //----W-Craft WebSquare 변환 확인: focus----//
        txb_fromEmail.focus();
        return false;
    }
    if (txb_title.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "제목");
        alert(msg);

        //----W-Craft WebSquare 변환 확인: focus----//
        txb_title.focus();
        return false;
    }
    if (txa_content.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "내용");
        alert(msg);

        //----W-Craft WebSquare 변환 확인: focus----//
        txa_content.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_EMP_NO) == "")	{
    	alert("세션정보를 받지 못했읍니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
    	txb_EMP_NO.focus();
    	return false;
    }
    */
    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    let total = 0;
    // TODO Stage2: 0-based 검토
    for (let i = 0; i <= dts_Receiver.getRowCount(); i++) {
        const chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk === "T" || chk === "1") {
            total++;
        }
    }
    if (total === 0) {
        alert("선택된 수신자가 없습니다.");
        return false;
    }
    if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test1' || js_svrGubun === 'test2') {
        alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
    }
    return true;
};

scwin.cancel = function() {
    scwin.setHeader();
    scwin.setData();

    dts_fileData.setJSON([]);
};

scwin.selectAll = function() {
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        // TODO Stage2: 0-based 검토
        for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i, "CHECK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        // TODO Stage2: 0-based 검토
        for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i, "CHECK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
};



