scwin.inf_find_OnClick = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************


    // TODO Stage2: 0-based 검토 / inf_find(레거시 파일 컴포넌트) 검토
    const filenm = FILE_NAME.getValue();
    dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.Value);
    txb_file_name.setValue(inf_find.Value);
    if (inf_find.Value === "") {
        txb_file_name.setValue(filenm);
    }
};

scwin.grd_fileList_OnDblClick = function(row, colid) {

    // TODO Stage2: RowStatus(row)===0 → getRowStatus 반환값("C"/"U"/"D"/"R") 비교 검토
    if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) === 0) {
        // TODO Stage2: 0-based 검토
        scwin.fn_filedown(dts_fileData.getCellData(row, "NOTI_SVC_ID"), dts_fileData.getCellData(row, "FILE_SEQ"));
    }
};

